import torch, json
E=W('model.embed_tokens.weight'); fn=W('model.embedding_norm.weight'); U=E*fn
Un=U/U.norm(dim=1,keepdim=True)
def ids(ws): return [encode(w)[0] for w in ws if len(encode(w))==1]
cats={
 'month':[' January',' February',' March',' April',' May',' June',' July',' August',' September',' October',' November',' December'],
 'weekday':[' Monday',' Tuesday',' Wednesday',' Thursday',' Friday',' Saturday',' Sunday'],
 'color':[' red',' blue',' green',' yellow',' black',' white',' purple',' orange',' pink',' brown'],
 'numword':[' one',' two',' three',' four',' five',' six',' seven',' eight',' nine',' ten',' eleven',' twelve'],
}
D={k:(lambda m:m/m.norm())(Un[ids(v)].mean(0)) for k,v in cats.items()}
out={}
for L in range(12,24):
    w2=W(f'model.layers.{L}.feed_forward.w2.weight')*W(f'model.layers.{L}.post_ffn_norm.weight')[:,None]
    cols=w2/w2.norm(dim=0,keepdim=True)
    for k in cats:
        s=(D[k]@cols).abs()
        v,i=s.topk(6)
        out[(k,L)]=(v.tolist(),i.tolist())
for k in cats:
    print(k)
    for L in range(12,24):
        v,i=out[(k,L)]; print('  ',L,[f'{a}:{b:.2f}' for a,b in zip(i,v)])
# attention heads OV through unembed
for L in range(24):
    if f'model.layers.{L}.self_attn.o_proj.weight' not in names(): continue
    o=W(f'model.layers.{L}.self_attn.o_proj.weight')
    pr=[]
    for h in range(16):
        oh=o[:,h*128:(h+1)*128]
        # projection energy of concept direction onto head output subspace
        q,_=torch.linalg.qr(oh)
        pr.append({k:round((q.T@D[k]).norm().item(),2) for k in cats})
    best={k:max(range(16),key=lambda h:pr[h][k]) for k in cats}
    print('attn L',L,{k:(best[k],pr[best[k]][k]) for k in cats})

E=W('model.embed_tokens.weight'); fn=W('model.embedding_norm.weight'); U=E*fn
def top(L,u,sg=1,k=15):
    w=W(f'model.layers.{L}.feed_forward.w2.weight')[:,u]*W(f'model.layers.{L}.post_ffn_norm.weight')
    return [decode([j]) for j in (sg*(U@w)).topk(k)[1].tolist()]
def inp(L,u,k=15):
    g=W(f'model.layers.{L}.feed_forward.w1.weight')[u]*W(f'model.layers.{L}.ffn_norm.weight')
    s=E@g; return [decode([j]) for j in s.topk(k)[1].tolist()],[decode([j]) for j in (-s).topk(10)[1].tolist()]
